const make = (base:string,args:string,purpose:string,when:string,example:string,output:string,next:string[],task:string,verify:string,flags:{flag:string;meaning:string}[]=[],safety?:string,workflow?:string[],pitfalls?:string[],level="Intermediate"):CommandGuide => ({
  base,args,purpose,when,flags,
  examples:[{label:"Practical operational example",command:example},{label:"Show supported options",command:base+" --help"}],
  output:output+"\n\nIllustrative output; exact values vary by version and environment.",
  next,task,verify,
  safety:safety||"Start with read-only inspection. Confirm host, user, context, namespace, region and target before changing state.",
  workflow:workflow||["Confirm target and current context.","Run a read-only inspection.","Capture output, timestamps and exit code.","Apply one approved change only if required.","Re-run checks and record evidence."],
  pitfalls:pitfalls||["Do not assume sample identifiers match your environment.","A successful command does not always prove application health."],
  level
});

